import json, html as H
CR=json.load(open("credits.json"))
NAMES={"hero":"Cotopaxi (home page)","quito":"Quito, Plaza Grande","mitad":"Mitad del Mundo","cotopaxi":"Cotopaxi National Park","quilotoa":"Quilotoa Lagoon","otavalo":"Otavalo market","cuenca":"Cuenca","banos":"Pailón del Diablo, Baños","chimborazo":"Chimborazo","mindo":"Mindo cloud forest","ingapirca":"Ingapirca","cajas":"El Cajas National Park","guayaquil":"Malecón 2000, Guayaquil","montanita":"Montañita","isla":"Isla de la Plata","frailes":"Los Frailes Beach","tena":"Napo River, Tena","cuyabeno":"Cuyabeno Wildlife Reserve","yasuni":"Yasuní National Park","santacruz":"Santa Cruz Island","sancristobal":"San Cristóbal Island","f_encebollado":"Encebollado","f_llapingachos":"Llapingachos","f_fanesca":"Fanesca","f_colada":"Colada morada & guaguas de pan","f_bolon":"Bolón de verde","f_maito":"Maito","f_hornado":"Hornado","wb_square":"Public Square, Wilkes-Barre, PA","wb_river":"Wilkes-Barre and the Susquehanna River"}
rows="".join(f'<li class="credit"><img src="img/{k}.jpg" alt="" loading="lazy"><div><b>{NAMES[k]}</b><span>Photo by {H.escape(H.unescape(v["artist"]))} · {v["lic"]}</span><a href="{v["page"]}">View on Wikimedia Commons ↗</a></div></li>' for k,v in CR.items())
cb = hero("Photo credits","Photo <em>credits</em>","Until our own photos take over, the pictures on this site come from photographers who share their work on Wikimedia Commons under open licenses. Thank you to each of them.") + f'''
<main><section><div class="wrap"><ul class="credits">{rows}</ul>
<p class="credit-note">Photos are shown resized and cropped. Licenses: Creative Commons (CC BY and CC BY-SA) and public domain, as listed on each photo's Commons page.</p></div></section></main>'''
page("photo-credits.html","Photo Credits · Latitude Zero","",cb)
